71	func (db hooksDatabase) ExecuteCommitHooks(ctx context.Context, ds datas.Dataset, onlyWS bool) {
72		var wg sync.WaitGroup
73		rsc := db.rsc
74		var ioff int
75		if rsc != nil {
76			ioff = len(rsc.Wait)
77			rsc.Wait = append(rsc.Wait, make([]func(context.Context) error, len(db.hooks))...)
78			rsc.NotifyWaitFailed = append(rsc.NotifyWaitFailed, make([]func(), len(db.hooks))...)
79		}
80		for il, hook := range db.hooks {
81			if !onlyWS || hook.ExecuteForWorkingSets() {
82				i := il
83				hook := hook
84				wg.Add(1)
85				go func() {
86					defer wg.Done()
87					// The error returned is intentionally ignored here. Hooks are expected to log errors themselves. The interface returns
88					// the error primarily for testing purposes.
89					f, _ := hook.Execute(ctx, ds, db.db)
90					if rsc != nil {
91						rsc.Wait[i+ioff] = f
92						if nf, ok := hook.(NotifyWaitFailedCommitHook); ok {
93							rsc.NotifyWaitFailed[i+ioff] = nf.NotifyWaitFailed
94						} else {
95							rsc.NotifyWaitFailed[i+ioff] = func() {}
96						}
97					}
98				}()
99			}
100		}
101		wg.Wait()
102		if rsc != nil {
103			j := ioff
104			for i := ioff; i < len(rsc.Wait); i++ {
105				// compact out any nil entries
106				if rsc.Wait[i] != nil {
107					rsc.Wait[j] = rsc.Wait[i]
108					rsc.NotifyWaitFailed[j] = rsc.NotifyWaitFailed[i]
109					j++
110				}
111			}
112			rsc.Wait = rsc.Wait[:j]
113			rsc.NotifyWaitFailed = rsc.NotifyWaitFailed[:j]
114		}
115	}
