40	func (s remotesrvStore) Get(ctx context.Context, path, _ string) (remotesrv.RemoteSrvStore, error) {
41		sqlCtx, err := s.ctxFactory(ctx)
42		if err != nil {
43			return nil, err
44		}
45		sess := dsess.DSessFromSess(sqlCtx.Session)
46		db, err := sess.Provider().Database(sqlCtx, path)
47		if err != nil {
48			if s.createDBs && sql.ErrDatabaseNotFound.Is(err) {
49				err = sess.Provider().CreateDatabase(sqlCtx, path)
50				if err != nil {
51					return nil, err
52				}
53				db, err = sess.Provider().Database(sqlCtx, path)
54				if err != nil {
55					return nil, err
56				}
57			} else {
58				return nil, err
59			}
60		}
61	
62		sdb, ok := db.(dsess.SqlDatabase)
63		if !ok {
64			return nil, remotesrv.ErrUnimplemented
65		}
66		ddb := sdb.DbData().Ddb
67		datasdb := doltdb.ExposeDatabaseFromDoltDB(ddb)
68		cs := datas.ChunkStoreFromDatabase(datasdb)
69		rss, ok := cs.(remotesrv.RemoteSrvStore)
70		if !ok {
71			return nil, remotesrv.ErrUnimplemented
72		}
73		return hooksFiringRemoteSrvStore{rss, ddb}, nil
74	}
